var t=`0122-blini`;var s=`world-0122`;var n=`RU`;var a=`eastern-europe`;var r=4;var l=31;var o={en:`Blini`,ua:`Млинці`};var g={en:`A classic dish from Russia, featuring whole cow milk, chicken egg, sour cream. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Росія. Основні складники: цільне коров'яче молоко, куряче яйце, сметана. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var h=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:10,i:[[`all-purpose-flour`,300,`g`],[`whole-cow-milk`,600,`ml`],[`chicken-egg`,3,`pcs`],[`instant-yeast`,6,`g`],[`white-granulated-sugar`,25,`g`],[`table-salt`,4,`g`]]},{en:`Swirl thin layers of batter in a lightly greased hot pan. Cook both sides, about 18 minutes per batch, to make flexible crepes.`,ua:`Наливайте тонкий шар тіста на злегка змащену розігріту сковороду. Обсмажуйте з обох боків, приблизно 18 хвилин на партію, щоб отримати еластичні млинці.`,t:[`pan-frying`],m:18,i:[[`unsalted-butter`,50,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`strawberry-jam`,130,`g`],[`sour-cream`,110,`g`]]}];var u={slug:t,id:s,country:`RU`,region:a,servings:4,minutes:31,title:o,text:g,steps:h};export{n as country,u as default,s as id,l as minutes,a as region,r as servings,t as slug,h as steps,g as text,o as title};